import{_ as r,l as o,o as t,c as n,v as e,p as s,x as i,d as p,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"BitFit","description":"","frontmatter":{"title":"BitFit","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/bitfit.md","filePath":"llm/bitfit.md","lastUpdated":1789023840000}'),h={name:"llm/bitfit.md"};function f(B,a,b,c,_,u){const l=o("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="bitfit" tabindex="-1">BitFit <a class="header-anchor" href="#bitfit" aria-label="Permalink to &quot;BitFit&quot;">​</a></h1><div class="epigraph"><p>只更新偏置项，可训练参数小到可以忽略，却仍能在不少分类式适应上移动决策面；它改的是每层的偏移，不是子空间。</p><footer>—— Ben Zaken、Goldberg、Ravfogel，BitFit: Simple Parameter-efficient Fine-tuning for Transformer，ACL 2022</footer></div><p><a href="/llm/relora">ReLoRA</a> 仍在玩矩阵增量。<a href="/llm/lora">LoRA</a> / VeRA 也是。BitFit 把问题拧到另一端：Transformer 里的偏置 \\(b\\) 本来几乎不被讨论，却是每层仿射 \\(Wx+b\\) 的平移。Ben Zaken 等人 2022 年表明，冻结 \\(W\\)、只训 \\(b\\)（及可选的任务头），在若干 GLUE 式任务上可接近全参。本课的缺口是：指令生成是否还买账；以及偏置适应在解码器 LLM 上能走多远。不把前缀调参（<a href="/llm/p-tuning-v2">下一课 P-tuning v2</a>）写成「也是只训一点点」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>适配器与 LoRA 引入新矩阵，改变或旁路计算图。若适应只需要把已有特征的阈值挪一挪——情感、蕴含、是否拒答——平移激活可能够用。偏置恰好是按通道的平移。问题：生成式 SFT 要改的是整段条件分布，不是单一 logit 阈值。只动 \\(b\\)，表达力是否够把<a href="/llm/instruction-data-lineage">谱系</a>里的助手口吻写进去？</p><p>第二条：许多 LLM 实现把偏置从线性层拿掉（Llama 风格），BitFit 无对象可训，只能动 LayerNorm 的 \\(\\beta\\)、或词表偏置。配方必须先清点「哪些 \\(b\\) 存在」。</p><h3 id="偏置不是低秩矩阵的特例" tabindex="-1">偏置不是低秩矩阵的特例 <a class="header-anchor" href="#偏置不是低秩矩阵的特例" aria-label="Permalink to &quot;偏置不是低秩矩阵的特例&quot;">​</a></h3><p>LoRA 的 \\(r=1\\) 仍在改 \\(W\\) 的一个方向。BitFit 完全不改 \\(W\\) 的列空间，只加与输入无关的向量。不能把 BitFit 当成 \\(r=0\\) 的 LoRA。几何不同，失败模式也不同：特征方向错了，平移救不了。</p><p><span class="marginnote">原文实验以编码器分类为主。迁移到解码器指令微调时，应当作弱基线：先看格式能否学会，再谈知识。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>冻结所有 \\(W\\) 与嵌入（除非任务加了新特殊 token），打开：注意力与 FFN 线性层的 bias（若有）、LayerNorm/RMSNorm 的仿射、LM head 的 bias（若有）。学习率可大于全参——参数极少——但仍远小于会打爆范数的值；按<a href="/llm/lora-vs-full-lr">适配器侧</a>的「大胆、但监控源域」来扫。SFT 用<a href="/llm/response-only-loss">仅回复</a>与同一<a href="/llm/chat-template">模板</a>。</p>',11)),(t(),s(m,null,{default:i(()=>[d(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%22%5D%20--%3E%20W%5B%22%E5%86%BB%E7%BB%93%20W%22%5D%0A%20%20W%20--%3E%20B%5B%22%E5%8F%AF%E8%AE%AD%E7%BB%83%20b%22%5D%0A%20%20B%20--%3E%20Y%5B%22Wx%20%2B%20b%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>若架构无 bias，BitFit 退化成「只训范数仿射」，能力更弱，应在报告里改名，不要冒充原文设定。可与 LoRA 比：同一数据上 BitFit 作为下限，LoRA \\(r=8\\) 作为常规。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(y=Wx+b\\) 里，\\(b\\) 不随 token 变。它能改变每个通道的触发点，从而改变后续非线性的工作区，间接改变注意力分数的分布。这对于「把某类特征推过阈值」有效。它不能增加新的特征组合方向——那需要改 \\(W\\) 或加秩。指令遵循若主要是「看到特殊 token 后切换说话方式」，而该切换已在预训练特征里，偏置或许能放大；若需要新的工具 JSON 语法，通常不够。</p><p>遗忘：几乎不动 \\(W\\)，源域特征保持最好，与 Biderman 等人对 LoRA 的「忘得少」同方向、更极端。学得也更少。</p><p><span class="marginnote">NEFTune 动嵌入表示；BitFit 动偏置。二者可叠，但都是弱干预。脏数据上 BitFit 过拟合偏置，表现为所有回复加上固定腔调偏移。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>生成任务、工具调用、领域术语内化，默认不要只靠 BitFit。分类、校准、轻度风格、作为消融基线，值得跑。服务期 BitFit 的检查点极小，可按用户存一份 \\(\\Delta b\\)，合并是向量加，无秩冲突——这比后课<a href="/llm/lora-merge-conflict">LoRA 合并</a>干净，前提是任务够简单。</p><p>无 bias 的 Llama 族上，优先 LoRA 而不是硬上 BitFit。P-tuning 走另一条「不改 \\(W\\)」：改前缀嵌入，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BitFit 只训偏置（及范数仿射），不改 \\(W\\) 的列空间。</li><li>对阈值型适应有效，对需要新方向的生成 SFT 通常不够。</li><li>许多解码器没有线性偏置，必须先清点参数。</li><li>遗忘极少、表达力天花板极低；适合当弱基线。</li><li>学习率按少量可训练参数取，仍须监控源域。</li><li>出处：Ben Zaken 等，BitFit，ACL 2022。</li></ul>',10))])}const L=r(h,[["render",f]]);export{F as __pageData,L as default};
